  "Trusted access link": "\u0935\u093f\u0936\u094d\u0935\u0938\u0928\u0940\u092f \u092a\u094d\u0930\u0935\u0947\u0936 \u0932\u093f\u0902\u0915",
  "Trusted access required": "\u0935\u093f\u0936\u094d\u0935\u0938\u0928\u0940\u092f \u092a\u0939\u0941\u0902\u091a \u0906\u0935\u0936\u094d\u092f\u0915",
  "Trusted access token": "\u0935\u093f\u0936\u094d\u0935\u0938\u0928\u0940\u092f \u090f\u0915\u094d\u0938\u0947\u0938 \u091f\u094b\u0915\u0928",
  "Trusted access token TTL (hours)": "\u0935\u093f\u0936\u094d\u0935\u0938\u0928\u0940\u092f \u090f\u0915\u094d\u0938\u0947\u0938 \u091f\u094b\u0915\u0928 \u091f\u0940\u091f\u0940\u090f\u0932 (\u0918\u0902\u091f\u0947)",
  "Type": "Type",
  "Type 'clear' to confirm": "\u092a\u0941\u0937\u094d\u091f\u093f \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f clear \u091f\u093e\u0907\u092a \u0915\u0930\u0947\u0902",
  "URL": "\u092f\u0942\u0906\u0930\u090f\u0932",
  "UUID": "UUID",
  "Unable to load submission.": "\u0938\u092c\u092e\u093f\u0936\u0928 \u0932\u094b\u0921 \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u0905\u0938\u092e\u0930\u094d\u0925",
  "Unable to load survey. Please try refreshing the page.": "\u0938\u0930\u094d\u0935\u0947 \u0932\u094b\u0921 \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u0905\u0938\u092e\u0930\u094d\u0925 \u0915\u0943\u092a\u092f\u093e \u092a\u0947\u091c \u0915\u094b \u0930\u093f\u092b\u094d\u0930\u0947\u0936 \u0915\u0930\u0928\u0947 \u0915\u093e \u092a\u094d\u0930\u092f\u093e\u0938 \u0915\u0930\u0947\u0902",
  "Unique Users": "Unique Users",
