  "Unsaved changes": "\u0905\u0938\u0939\u0947\u091c\u0947 \u0917\u090f \u092a\u0930\u093f\u0935\u0930\u094d\u0924\u0928",
  "Untitled": "Untitled",
  "Unused": "Unused",
  "Update": "\u0905\u092a\u0921\u0947\u091f",
  "Upload": "\u0905\u092a\u0932\u094b\u0921",
  "Upload JSON form schema": "JSON \u092b\u0949\u0930\u094d\u092e \u0938\u094d\u0915\u0940\u092e\u093e \u0905\u092a\u0932\u094b\u0921 \u0915\u0930\u0947\u0902",
  "Upload PDF": "\u092a\u0940\u0921\u0940\u090f\u092b \u0905\u092a\u0932\u094b\u0921 \u0915\u0930\u0947\u0902",
  "Upload PDF Template": "Upload PDF Template",
  "Upload Theme JSON": "Upload Theme JSON",
  "Upload a PDF form and generate SurveyJS JSON from it": "\u090f\u0915 \u092a\u0940\u0921\u0940\u090f\u092b \u092b\u0949\u0930\u094d\u092e \u0905\u092a\u0932\u094b\u0921 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0909\u0938\u0938\u0947 SurveyJS JSON \u091c\u0928\u0930\u0947\u091f \u0915\u0930\u0947\u0902",
  "Upload a fillable PDF form (.pdf file only)": "Upload a fillable PDF form (.pdf file only)",
  "Upload a fillable PDF to generate a SurveyJS form and enable PDF-based submissions.": "\u090f\u0915 \u092d\u0930\u0928\u0947 \u092f\u094b\u0917\u094d\u092f PDF \u0905\u092a\u0932\u094b\u0921 \u0915\u0930\u0947\u0902 \u0924\u093e\u0915\u093f \u090f\u0915 SurveyJS \u092b\u0949\u0930\u094d\u092e \u091c\u0947\u0928\u0930\u0947\u091f \u0939\u094b \u0938\u0915\u0947 \u0914\u0930 PDF \u0906\u0927\u093e\u0930\u093f\u0924 \u0938\u092c\u092e\u093f\u0936\u0928 \u0938\u0915\u094d\u0937\u092e \u0939\u094b \u0938\u0915\u0947\u0902",
  "Upload a source document and generate a temporary SurveyJS form draft with AI.": "\u090f\u0915 \u0938\u094d\u0930\u094b\u0924 \u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c \u0905\u092a\u0932\u094b\u0921 \u0915\u0930\u0947\u0902 \u0914\u0930 AI \u0915\u0947 \u0938\u093e\u0925 \u0905\u0938\u094d\u0925\u093e\u092f\u0940 SurveyJS \u092b\u093c\u0949\u0930\u094d\u092e \u0921\u094d\u0930\u093e\u092b\u094d\u091f \u091c\u0928\u0930\u0947\u091f \u0915\u0930\u0947\u0902\u0964",
  "Upload a valid SurveyJS JSON file to create a new version. The file will be validated before saving.": "\u090f\u0915 \u0928\u092f\u093e \u0938\u0902\u0938\u094d\u0915\u0930\u0923 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u090f\u0915 \u092e\u093e\u0928\u094d\u092f SurveyJS JSON \u092b\u093c\u093e\u0907\u0932 \u0905\u092a\u0932\u094b\u0921 \u0915\u0930\u0947\u0902 \u092b\u093c\u093e\u0907\u0932 \u0915\u094b \u0938\u0939\u0947\u091c\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u092e\u093e\u0928\u094d\u092f \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e",
  "Upload and Convert": "\u0905\u092a\u0932\u094b\u0921 \u0914\u0930 \u0915\u0928\u0935\u0930\u094d\u091f \u0915\u0930\u0947\u0902",
  "Upload and Create Version": "\u0938\u0902\u0938\u094d\u0915\u0930\u0923 \u0905\u092a\u0932\u094b\u0921 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092c\u0928\u093e\u090f\u0901",
  "Upload documents and convert them to SurveyJS forms using AI": "AI \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0915\u0947 \u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c \u0905\u092a\u0932\u094b\u0921 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0909\u0928\u094d\u0939\u0947\u0902 SurveyJS \u092b\u093c\u0949\u0930\u094d\u092e \u092e\u0947\u0902 \u092c\u0926\u0932\u0947\u0902",
